B.XQ=s(["Increase by 1 mg/kg/min, maximum 10 mg/kg/min","Increase by 2 mg/kg/min, maximum 12 mg/kg/min","Increase by 4 mg/kg/min, maximum 16 mg/kg/min","Double the GIR each hour"],t.s)
B.So=new A.cf("hypo_mcq_6","On IV glucose, if BG remains < 45 mg/dL, how does the STW change the GIR?",B.XQ,1,'Flowchart: BG < 45 mg/dL \u2192 "Increase GIR by 2 mg/ kg/min (maximum 12 mg/kg/min)".',"Increasing GIR",null,u.g0)
B.X_=s([u.cG,"Hydrocortisone: 10 mg/kg/day IV once daily","Dexamethasone 6 mg IM every 12 hours","Oral dextrose solution"],t.s)
